package api

import("context";"encoding/json";"fmt";"github.com/softrenzu/Prometheus/internal/engine";"net/http";"net/url";"strconv";"strings";"time")
func(s *Server)queryPeers(ctx context.Context,ten,expr string,start,end,step int64)[]engine.Series{out:=[]engine.Series{};client:=&http.Client{Timeout:2*time.Second};for _,peer:=range s.Peers{u:=strings.TrimRight(peer,"/")+"/internal/query?query="+url.QueryEscape(expr);if start>0{u+=fmt.Sprintf("&range=1&start=%f&end=%f&step=%f",float64(start)/1000,float64(end)/1000,float64(step)/1000)};req,err:=http.NewRequestWithContext(ctx,"GET",u,nil);if err!=nil{continue};req.Header.Set("X-Scope-OrgID",ten);req.Header.Set("X-Rooom-Internal","1");resp,err:=client.Do(req);if err!=nil{continue};var p struct{Data struct{Result []struct{Metric map[string]string `json:"metric"`;Value []json.RawMessage `json:"value"`;Values [][]json.RawMessage `json:"values"`} `json:"result"`} `json:"data"`};err=json.NewDecoder(resp.Body).Decode(&p);resp.Body.Close();if err!=nil{continue};for _,r:=range p.Data.Result{metric:=r.Metric["__name__"];delete(r.Metric,"__name__");ss:=engine.Series{Tenant:ten,Metric:metric,Labels:r.Metric};if len(r.Value)==2{ss.Points=append(ss.Points,rawPoint(r.Value))};for _,pair:=range r.Values{if len(pair)==2{ss.Points=append(ss.Points,rawPoint(pair))}};out=append(out,ss)}};return out}
func rawPoint(pair []json.RawMessage)engine.Point{var ts float64;var vs string;_=json.Unmarshal(pair[0],&ts);_=json.Unmarshal(pair[1],&vs);v,_:=strconv.ParseFloat(vs,64);return engine.Point{Timestamp:int64(ts*1000),Value:v}}
